CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS user_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), privy_user_id text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), address text NOT NULL CHECK (address = lower(address)), is_canonical boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,address));
CREATE UNIQUE INDEX IF NOT EXISTS one_canonical_wallet_per_account ON wallets(account_id) WHERE is_canonical;
CREATE TABLE IF NOT EXISTS holder_eligibility (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), wallet_address text NOT NULL, state text NOT NULL CHECK (state IN ('eligible','insufficient_balance','wrong_wallet','wrong_network','rpc_failure','token_misconfiguration')), chain_id integer, token_address text, balance_raw numeric(78,0), token_decimals integer, threshold_raw numeric(78,0), verified_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS holder_eligibility_account_time ON holder_eligibility(account_id, verified_at DESC);
CREATE TABLE IF NOT EXISTS compute_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), amount_micro_usd bigint NOT NULL CHECK (amount_micro_usd > 0), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, recurrence_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id, recurrence_key));
CREATE TABLE IF NOT EXISTS compute_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), operation_key text NOT NULL UNIQUE, reserved_micro_usd bigint NOT NULL CHECK (reserved_micro_usd > 0), settled_micro_usd bigint NOT NULL DEFAULT 0, provider_cost_micro_usd bigint, status text NOT NULL CHECK (status IN ('reserved','settled','released','uncertain')), uncertain boolean NOT NULL DEFAULT false, settled_at timestamptz);
CREATE TABLE IF NOT EXISTS compute_ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), grant_id uuid REFERENCES compute_grants(id), reservation_id uuid REFERENCES compute_reservations(id), entry_type text NOT NULL CHECK (entry_type IN ('grant','reservation','user_debit','release','refund','adjustment')), amount_micro_usd bigint NOT NULL CHECK (amount_micro_usd > 0), idempotency_key text NOT NULL UNIQUE, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inference_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES user_accounts(id), operation_key text NOT NULL UNIQUE, provider text NOT NULL, model text NOT NULL, status text NOT NULL CHECK (status IN ('started','streaming','complete','cancelled','failed','uncertain')), input_tokens integer, output_tokens integer, provider_cost_micro_usd bigint, user_debit_micro_usd bigint, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());

ALTER TABLE holder_eligibility DROP CONSTRAINT IF EXISTS holder_eligibility_state_check;
ALTER TABLE holder_eligibility ADD CONSTRAINT holder_eligibility_state_check CHECK (state IN ('eligible','insufficient_balance','wrong_wallet','wrong_network','rpc_failure','token_misconfiguration')); 
